SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, COUNT(*) FILTER (WHERE country = 'TH') AS th_rows, COUNT(DISTINCT id) AS distinct_ids, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, COUNT(CASE WHEN browser = 'Firefox' THEN 1 END) AS firefox_count, COUNT(CASE WHEN country = 'UK' THEN 1 END) AS uk_count FROM sessions GROUP BY DATE_TRUNC('MONTH', started_at) HAVING COUNT(CASE WHEN country = 'UK' THEN 1 END) > 1
